SELECT stddev(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_sd FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND p.anchor_year = 42 AND a.admission_type = 'DAPT' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND p.subject_id IN (SELECT subject_id FROM patients WHERE EXTRACT(YEAR FROM age(CURRENT_DATE, dod)) BETWEEN 37 AND 47);